from pathlib import Path
import json,copy,hashlib,re
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent
PRIOR=ROOT/'reviews/codex-supervision/2026-10-05-strict-batch-audit'
BASE=json.loads((PRIOR/'scope-and-baseline-v2.json').read_text(encoding='utf-8'))
OLD={};BATCH={};NEW={}
for batch in BASE['selected']:
 for row in map(json.loads,(OUT/'before'/f'{batch}.jsonl').read_text(encoding='utf-8').splitlines()):OLD[row['id']]=row;BATCH[row['id']]=batch
POLICY=json.loads((ROOT/'configs/training_diversity_policy.json').read_text(encoding='utf-8'))
CONCEPT={r['id']:r for r in POLICY['concepts']}
def add(old,cid,problem,solution,answer,method,kind,steps,objects):
 assert old not in NEW
 NEW[old]={'concept_id':cid,'problem':problem,'solution':solution,'answer':answer,'method':method,'variant_kind':kind,'scene_spec':{'objects':objects,'steps':steps}}
