def normalize_math(value):
 if isinstance(value,str):
  return re.sub(r'\\{2,}(?=[A-Za-z])',lambda m:chr(92),value)
 if isinstance(value,list):return [normalize_math(v) for v in value]
 if isinstance(value,dict):return {k:normalize_math(v) for k,v in value.items()}
 return value

